src/css/components/field.css.content:
/* Field */
@layer components {
  .fieldset {
    @apply flex flex-col;
  }

  .fieldset > :is([role='group'], [role='radiogroup']):not(.field),
  .field > :is(fieldset, [role='group'], [role='radiogroup']):not(.field) {
    @apply @container/field-group flex w-full flex-col;
  }

  .field {
    @apply flex w-full flex-col data-invalid:text-destructive data-[invalid=true]:text-destructive [&>*]:w-full [&>.sr-only]:w-auto;

    &[data-orientation='horizontal'] {
      @apply flex-row items-center [&>*]:w-auto [&>label]:flex-auto has-[>section]:items-start has-[>section]:[&>section]:flex-1 has-[>section]:[&>[type=checkbox],[type=radio]]:mt-px [&_p]:text-balance;
    }

    &[data-orientation='responsive'] {
      @apply flex-col @md/field-group:flex-row @md/field-group:items-center @md/field-group:[&>*]:w-auto @md/field-group:has-[>section]:items-start @md/field-group:[&>label]:flex-auto @md/field-group:has-[>section]:[&>[type=checkbox],[type=radio]]:mt-px;
    }

    section {
      @apply flex flex-1 flex-col leading-snug;
    }

    h2,
    h3 {
      @apply flex w-fit items-center;
    }

    [role='alert'] {
      @apply font-normal;

      ul {
        @apply ms-4 flex list-disc flex-col gap-1;
      }
    }
  }

  .field > label,
  .field > section > label,
  label:has(> .field) {
    @apply w-fit;
  }

  .field > label:has(> .field),
  .field > label:has(input[type='radio']),
  .field > label:has(input[type='checkbox']),
  .field > label:has(input[role='switch']),
  label:has(> .field) {
    @apply w-full;
  }

  .field > label:has(> .field),
  label:has(> .field) {
    @apply flex-col;
  }

  .fieldset legend + p,
  .field > p,
  .field section > p {
    @apply leading-normal font-normal [&>a:hover]:text-primary [&>a]:underline [&>a]:underline-offset-4;
  }

  .field > p,
  .field section > p {
    @apply last:mt-0 nth-last-2:-mt-1;
  }

  .field-separator {
    @apply relative;
  }

  .field-separator > hr[role='separator'] {
    @apply absolute inset-x-0 top-1/2;
  }

  .field-separator > span {
    @apply relative mx-auto block w-fit bg-background;
  }
}

src/css/components/card.css.content:
/* Card */
@layer components {
  .card {
    @apply flex flex-col;

    > header {
      @apply @container/card-header grid auto-rows-min items-start has-[>[data-slot=card-action],>.card-action]:grid-cols-[1fr_auto] has-[>p]:grid-rows-[auto_auto];
    }

    > header > :is(h2, h3, [data-title], .card-title) {
      @apply leading-none;
    }

    > header > :is([data-slot='card-action'], .card-action) {
      @apply col-start-2 row-span-2 row-start-1 self-start justify-self-end;
    }

    > header > menu.card-action {
      @apply m-0 list-none p-0;
    }

    > footer {
      @apply flex items-center;
    }
  }
}

excerpts.card:
/* Card */
.card {
  @apply ring-foreground/10 bg-card text-card-foreground overflow-hidden rounded-xl text-sm shadow-xs ring-1 has-[>img:first-child]:pt-0 [&>img:first-child]:rounded-t-xl [&>img:last-child]:rounded-b-xl;
}

.card {
  @apply gap-6 py-6;
}

.card[data-size='sm'] {
  @apply gap-4 py-4;
}

.card > header {
  @apply gap-1 rounded-t-xl px-6 [.border-b]:pb-6;
}

.card[data-size='sm'] > header {
  @apply px-4 [.border-b]:pb-4;
}

.card > header > :is(h2, h3, [data-title], .card-title) {
  @apply text-base leading-normal font-medium;
}

.card[data-size='sm'] > header > :is(h2, h3, [data-title], .card-title) {
  @apply text-sm;
}

.card > header > :is(p, [data-description], .card-description) {
  @apply text-muted-foreground text-sm;
}

.card > section {
  @apply px-6;
}

.card[data-size='sm'] > section {
  @apply px-4;
}

.card > footer {
  @apply rounded-b-xl px-6 [.border-t]:pt-6;
}

.card[data-size='sm'] > footer {
  @apply px-4 [.border-t]:pt-4;
}

excerpts.field:
/* Field */
.fieldset {
  @apply gap-6 has-[>[data-slot=checkbox-group]]:gap-3 has-[>[data-slot=radio-group]]:gap-3;
}

.fieldset > legend {
  @apply mb-3 font-medium data-[variant=label]:text-sm data-[variant=legend]:text-base;
}

.fieldset > :is([role='group'], [role='radiogroup']):not(.field),
.field > :is(fieldset, [role='group'], [role='radiogroup']):not(.field) {
  @apply gap-7;

  &[role='radiogroup'],
  &:has(> .field > input[type='checkbox']:not([role='switch'])),
  &:has(> .field > input[type='radio']),
  &[data-slot='checkbox-group'],
  &[data-slot='radio-group'] {
    @apply gap-3;
  }
}

:is(.fieldset, .field) > :is([role='group'], [role='radiogroup']):not(.field) > :is([role='group'], [role='radiogroup']):not(.field),
.field > fieldset:not(.field) > :is([role='group'], [role='radiogroup']):not(.field) {
  @apply gap-4;
}

.field {
  @apply data-invalid:text-destructive data-[invalid=true]:text-destructive gap-3;
}

.field > section {
  @apply gap-1;
}

.field > label,
.field > section > label,
label:has(> .field) {
  @apply has-[:checked]:bg-primary/5 has-[:checked]:border-primary/30 dark:has-[:checked]:border-primary/20 dark:has-[:checked]:bg-primary/10 gap-2 leading-snug in-data-[disabled=true]:opacity-50;
}

.field > label:has(input[type='radio']),
.field > label:has(input[type='checkbox']),
.field > label:has(input[role='switch']),
.field > label:has(> .field),
label:has(> .field) {
  @apply rounded-md border;
}

.field > label:has(input[type='radio']),
.field > label:has(input[type='checkbox']),
.field > label:has(input[role='switch']) {
  @apply p-3;
}

:is(.field > label, label:has(> .field)) > .field {
  @apply p-3;
}
.field h2,
.field h3 {
  @apply gap-2 leading-snug text-sm font-medium in-data-[disabled=true]:opacity-50;
}

.fieldset legend + p,
.field > p,
.field section > p {
  @apply text-muted-foreground text-start text-sm [[data-variant=legend]+&]:-mt-1.5;
}

.fieldset > legend[data-variant='label'] {
  @apply mb-0;
}

.fieldset > legend:not([data-variant]) + p,
.fieldset > legend[data-variant='legend'] + p {
  @apply -mt-1.5;
}

.field-separator {
  @apply -my-2 h-5 text-sm in-data-[variant=outline]:-mb-2;
}

.field-separator > span {
  @apply text-muted-foreground px-2;
}

.field [role="alert"] {
  @apply text-destructive text-sm;
}
